changeSet.sql:
UPDATE payments SET currency = 'EUR', reconciliation_issue = NULL
    WHERE provider_payment_id = 'seed-stripe-payment-002';
UPDATE orders o JOIN payments p ON p.order_id = o.id
    SET o.currency = p.currency
    WHERE p.provider_payment_id = 'seed-stripe-payment-002';
UPDATE orders SET currency = 'UAH' WHERE currency IS NULL;
